import { useState } from "react";
import { Link } from "react-router-dom";
import { FiMenu, FiX } from "react-icons/fi";
import styles from "./Header.module.scss";
import Logo from "../common/Logo/Logo";
import HeaderNavBar from "../HeaderNavBar/HeaderNavBar";
import DarkModeToggle from "../common/DarkModeToggle/DarkModeToggle";
import AuthButtons from "../common/AuthButtons/AuthButtons";
import MobileMenu from "../MobileMenu/MobileMenu";

const Header = () => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState<boolean>(false);

  const toggleMobileMenu = () => {
    setIsMobileMenuOpen((prev) => !prev);
  };

  return (
    <header>
      <div className={styles["header__content"]} role="banner">
        <Link className={styles["header__logo"]} aria-label="Home">
          <Logo />
        </Link>
        <nav className={styles["header__nav"]} role="navigation">
          <HeaderNavBar />
        </nav>
        <div className={styles["header__actions"]}>
          <DarkModeToggle />
          <AuthButtons />
        </div>
        <button
          className={styles["header__mobileMenu"]}
          onClick={toggleMobileMenu}
          aria-label="Toggle menu"
        >
          {isMobileMenuOpen ? <FiX size={24} /> : <FiMenu size={24} />}
        </button>
        {isMobileMenuOpen && <MobileMenu closeMenu={toggleMobileMenu} />}
      </div>
    </header>
  );
};

export default Header;
